// Parsear datos del sitio recibidos del workflow principal
const siteDataStr = $input.item.json.siteData;
const siteData = typeof siteDataStr === 'string' ? JSON.parse(siteDataStr) : siteDataStr;

// Calcular fecha de lookback
const lookbackDays = siteData.Lookback_Days || 30;
const lookbackDate = new Date();
lookbackDate.setDate(lookbackDate.getDate() - lookbackDays);
const isoDate = lookbackDate.toISOString();

// Construir URL de WordPress API
const siteUrl = siteData.Sitio_URL;
const apiUrl = `${siteUrl}/wp-json/wp/v2/posts?after=${isoDate}&per_page=50&_embed&orderby=date&order=desc`;

// Timestamp de inicio
const startTime = Date.now();

return {
  json: {
    ...siteData,
    lookback_date: isoDate,
    wp_api_url: apiUrl,
    start_time: startTime,
    processing_step: 'INITIALIZED'
  }
};

// Validar respuesta de WordPress API
const response = $input.item.json;
const siteData = $input.first().json;

// Verificar si hubo error en la llamada
if (response.error || !response || (Array.isArray(response) && response.length === 0 && response.error)) {
  return {
    json: {
      ...siteData,
      api_call_success: false,
      api_error: true,
      error_message: response.error?.message || response.message || 'WordPress API no retornó datos',
      error_code: response.error?.code || response.statusCode || 'UNKNOWN',
      articles: [],
      processing_step: 'WP_API_ERROR'
    }
  };
}

// Si es un array vacío pero sin error, es sitio sin contenido nuevo
if (Array.isArray(response) && response.length === 0) {
  return {
    json: {
      ...siteData,
      api_call_success: true,
      api_error: false,
      articles: [],
      processing_step: 'NO_NEW_CONTENT'
    }
  };
}

// Llamada exitosa con artículos
const articles = Array.isArray(response) ? response : [response];

return {
  json: {
    ...siteData,
    api_call_success: true,
    api_error: false,
    raw_articles: articles,
    raw_articles_count: articles.length,
    processing_step: 'WP_API_SUCCESS'
  }
};

// Retornar error de API al workflow principal
const siteData = $input.item.json;
const executionTime = Date.now() - siteData.start_time;

return {
  json: {
    site_domain: siteData.site_domain,
    Sitio_URL: siteData.Sitio_URL,
    status: 'FAILED',
    error_type: 'WP_API_ERROR',
    error_message: siteData.error_message || 'Error al conectar con WordPress API',
    error_code: siteData.error_code || 'UNKNOWN',
    api_error: true,
    articles_processed: 0,
    execution_time_ms: executionTime
  }
};

// Extraer y limpiar contenido de artículos
const siteData = $input.item.json;
const rawArticles = siteData.raw_articles || [];

// Función para limpiar HTML y extraer primeros párrafos
function extractFirstParagraphs(htmlContent, maxParagraphs = 3) {
  if (!htmlContent) return '';

  let cleaned = htmlContent
    .replace(/<script[^>]*>.*?<\/script>/gis, '')
    .replace(/<style[^>]*>.*?<\/style>/gis, '')
    .replace(/<\/?[^>]+(>|$)/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();

  const paragraphs = cleaned.split(/\.\s+(?=[A-Z])/).filter(p => p.trim().length > 50);
  const selectedParagraphs = paragraphs.slice(0, maxParagraphs).join('. ');

  return selectedParagraphs.substring(0, 1200) + (selectedParagraphs.length > 1200 ? '...' : '');
}

// Procesar cada artículo
const processedArticles = rawArticles.map(article => {
  const content = article.content?.rendered || article.excerpt?.rendered || '';
  const extractedContent = extractFirstParagraphs(content, 3);

  return {
    title: article.title?.rendered || 'Sin título',
    url: article.link || article.guid?.rendered || '',
    date: article.date || new Date().toISOString(),
    excerpt_for_ai: extractedContent,
    word_count: extractedContent.split(/\s+/).length,
    author: article._embedded?.author?.[0]?.name || 'Desconocido'
  };
}).filter(article => article.word_count > 20);

return {
  json: {
    ...siteData,
    articles: processedArticles,
    total_articles: processedArticles.length,
    has_content: processedArticles.length > 0,
    processing_step: processedArticles.length > 0 ? 'CONTENT_EXTRACTED' : 'NO_VALID_CONTENT'
  }
};

// Retornar resultado de sitio sin contenido nuevo
const siteData = $input.item.json;
const executionTime = Date.now() - siteData.start_time;

return {
  json: {
    site_domain: siteData.site_domain,
    Sitio_URL: siteData.Sitio_URL,
    status: 'SKIPPED',
    error_type: 'NO_NEW_CONTENT',
    error_message: `No hay artículos nuevos en los últimos ${siteData.Lookback_Days || 30} días`,
    articles_processed: 0,
    execution_time_ms: executionTime
  }
};

// Validar respuesta del subworkflow de AI
const aiResponse = $input.item.json;
const siteData = $input.first().json;

// Verificar si hubo error en el subworkflow de AI
if (aiResponse.error || aiResponse.status === 'FAILED') {
  // AI falló, usar insights genéricos
  const articlesWithGenericInsights = siteData.articles.map(article => ({
    title: article.title,
    url: article.url,
    date: article.date,
    insight: `Contenido relevante sobre ${siteData.site_domain}. Consulte el artículo completo para más detalles.`
  }));

  return {
    json: {
      ...siteData,
      processed_articles: articlesWithGenericInsights,
      insights_count: articlesWithGenericInsights.length,
      ai_success: false,
      ai_fallback_used: true,
      processing_step: 'AI_FALLBACK'
    }
  };
}

// AI exitoso
return {
  json: {
    ...siteData,
    processed_articles: aiResponse.processed_articles || [],
    insights_count: aiResponse.insights_count || 0,
    ai_success: true,
    ai_fallback_used: false,
    ai_execution_time_ms: aiResponse.execution_time_ms || 0,
    processing_step: 'AI_SUCCESS'
  }
};

// Construir el archivo llms.txt completo
const siteData = $input.item.json;
const processedArticles = siteData.processed_articles || [];
const siteDomain = siteData.site_domain;
const siteUrl = siteData.Sitio_URL;

// Header del archivo
const header = `# ${siteDomain}

> Portal de Infraestructura y Logística - Insights de Impacto para Deep Research
> Actualizado: ${new Date().toISOString().split('T')[0]}
> Artículos procesados: ${processedArticles.length}
> IA utilizada: ${siteData.ai_fallback_used ? 'Fallback genérico' : 'Claude/Gemini'}

## Recursos principales

- Sitio web: ${siteUrl}
- RSS Feed: ${siteUrl}/feed/
- API: ${siteUrl}/wp-json/wp/v2/

---

## Insights de Impacto Recientes

`;

// Sección de artículos
const articlesSection = processedArticles.map((article, index) => {
  return `### ${index + 1}. [${article.title}](${article.url})

**Insight:** ${article.insight}

**Fecha:** ${new Date(article.date).toISOString().split('T')[0]}

**URL:** ${article.url}

---
`;
}).join('\n');

// Footer
const footer = `
## Sobre este archivo

Este archivo llms.txt ha sido generado automáticamente para optimizar la recuperación de información por modelos de lenguaje de gran escala (LLMs).

**Objetivos:**
- Investigación profunda (Deep Research)
- Análisis de inversiones en infraestructura
- Inteligencia de mercado logístico
- Toma de decisiones basada en datos

**Metodología:**
Extracción automática de métricas clave, cifras financieras y análisis de impacto mediante AI.

**Actualización:**
Este archivo se regenera automáticamente cada ${siteData.Lookback_Days || 30} días.

**Procesamiento:**
- Sistema: n8n Community Edition v2.0
- Última ejecución: ${new Date().toISOString()}
- Artículos analizados: ${processedArticles.length}

**Contacto:**
Para más información, visite ${siteUrl}

---

*Generado automáticamente por LLMS.txt Auto-Updater*
`;

// Archivo completo
const llmsTxtContent = header + articlesSection + footer;
const fileSize = Buffer.from(llmsTxtContent, 'utf-8').length;

return {
  json: {
    ...siteData,
    llms_txt_content: llmsTxtContent,
    file_size: fileSize,
    processing_step: 'LLMS_TXT_BUILT'
  }
};

// Upload dinámico vía sFTP usando ssh2-sftp-client
// NOTA: Requiere 'npm install ssh2-sftp-client' en servidor n8n

const SftpClient = require('ssh2-sftp-client');
const sftp = new SftpClient();

const siteData = $input.item.json;

const config = {
  host: siteData.sFTP_Host,
  port: 22,
  username: siteData.sFTP_User,
  password: siteData.sFTP_Pass,
  readyTimeout: 20000,
  retries: 2,
  retry_factor: 2,
  retry_minTimeout: 2000
};

const remotePath = '/public_html/llms.txt';
const localContent = Buffer.from(siteData.llms_txt_content, 'utf-8');

try {
  await sftp.connect(config);

  // Verificar directorio
  const remoteDir = remotePath.substring(0, remotePath.lastIndexOf('/'));
  const dirExists = await sftp.exists(remoteDir);
  if (!dirExists) {
    await sftp.mkdir(remoteDir, true);
  }

  // Subir archivo
  await sftp.put(localContent, remotePath);

  // Verificar upload
  const fileInfo = await sftp.stat(remotePath);

  await sftp.end();

  return {
    json: {
      ...siteData,
      upload_status: 'SUCCESS',
      sftp_success: true,
      uploaded_file_size: fileInfo.size,
      processing_step: 'UPLOAD_SUCCESS'
    }
  };

} catch (error) {
  try { await sftp.end(); } catch (e) {}

  return {
    json: {
      ...siteData,
      upload_status: 'FAILED',
      sftp_success: false,
      sftp_error: true,
      error_message: error.message,
      error_code: error.code || 'SFTP_ERROR',
      processing_step: 'UPLOAD_FAILED'
    }
  };
}

// Retornar resultado exitoso al workflow principal
const siteData = $input.item.json;
const executionTime = Date.now() - siteData.start_time;

return {
  json: {
    site_domain: siteData.site_domain,
    Sitio_URL: siteData.Sitio_URL,
    status: 'SUCCESS',
    articles_processed: siteData.insights_count || 0,
    file_size: siteData.file_size || 0,
    insights_count: siteData.insights_count || 0,
    upload_status: 'SUCCESS',
    ai_fallback_used: siteData.ai_fallback_used || false,
    execution_time_ms: executionTime,
    llms_txt_url: `${siteData.Sitio_URL}/llms.txt`
  }
};

// Retornar resultado con fallo de upload
const siteData = $input.item.json;
const executionTime = Date.now() - siteData.start_time;

return {
  json: {
    site_domain: siteData.site_domain,
    Sitio_URL: siteData.Sitio_URL,
    status: 'FAILED',
    error_type: 'SFTP_ERROR',
    error_message: siteData.error_message || 'Error al subir archivo vía sFTP',
    sftp_error: true,
    articles_processed: siteData.insights_count || 0,
    file_size: siteData.file_size || 0,
    execution_time_ms: executionTime
  }
};
